/* Daily attendance uses the existing protected sessions ledger. */
let attendanceDay=AcademyDates.today();const attendanceSaving=new Set();
const tehranDay=value=>new Date(value).toLocaleDateString('en-CA',{timeZone:'Asia/Tehran'});
function dailyClassRows(){
 const rows=db.sessions.filter(c=>tehranDay(c.starts_at)===attendanceDay).map(c=>({student:db.students.find(s=>s.id===c.student_id),session:c,time:new Date(c.starts_at).toLocaleTimeString('en-GB',{timeZone:'Asia/Tehran',hour:'2-digit',minute:'2-digit'}),paid:(()=>{const t=monthRows.find(t=>t.student_id===c.student_id&&t.dates.includes(attendanceDay));return t?!!t.paid[t.dates.indexOf(attendanceDay)]:!!eligible(db.students.find(s=>s.id===c.student_id)||{});})()}));
 for(const t of monthRows){if(!t.published)continue;const i=t.dates.indexOf(attendanceDay),s=db.students.find(s=>s.id===t.student_id);if(i<0||!s||s.archived_at||rows.some(r=>r.student?.id===s.id))continue;rows.push({student:s,time:s.class_time.slice(0,5),paid:!!t.paid[i],session:null});}
 return rows.filter(r=>r.student&&!r.student.archived_at).sort((a,b)=>a.time.localeCompare(b.time));
}
function attendancePanel(){if(!admin)return '';const rows=dailyClassRows();return `<div class="card daily-attendance"><div class="cardhead"><div><h3>کلاس‌های روز و حضور هنرجویان</h3><p class="sub">${AcademyDates.show(attendanceDay)} · ${money(rows.length)} کلاس</p></div><div class="daily-controls"><button onclick="shiftAttendanceDay(-1)" aria-label="روز قبل">→</button><button onclick="attendanceDay=AcademyDates.today();render()">امروز</button><button onclick="shiftAttendanceDay(1)" aria-label="روز بعد">←</button></div></div>${table(['ساعت','هنرجو','استاد و رشته','وضعیت','ثبت حضور'],rows.map((r,i)=>`<tr><td dir="ltr"><b>${r.time}</b></td><td>${esc(full(r.student))}</td><td>${window.teacherInline?window.teacherInline(teacher(r.student.teacher_id)):esc(teacher(r.student.teacher_id))}<small class="sub">${esc(r.student.subject)}</small></td><td><span class="badge">${r.session?esc(statusLabel(r.session.status)):r.paid?'آمادهٔ حضور':'شهریه پرداخت نشده'}</span></td><td>${(!r.session||r.session.status==='scheduled')?`<button class="primary" onclick="markDailyAttendance('${r.student.id}','completed',this)" ${!r.paid||attendanceDay>AcademyDates.today()?'disabled':''}>✓ حاضر</button> <button onclick="markDailyAttendance('${r.student.id}','absent',this)" ${!r.paid||attendanceDay>AcademyDates.today()?'disabled':''}>غایب</button>`:'ثبت شد'}</td></tr>`))}<p class="sub">حضور فقط برای جلسهٔ پرداخت‌شده و روز جاری یا گذشته ثبت می‌شود. جلسات ثبت‌شده دوباره قابل تأیید نیستند.</p></div>`;}
function shiftAttendanceDay(offset){const d=new Date(attendanceDay+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+offset);attendanceDay=d.toISOString().slice(0,10);render();}
async function markDailyAttendance(studentId,status,button){if(!admin||attendanceSaving.has(studentId)||!['completed','absent'].includes(status))return;const r=dailyClassRows().find(r=>r.student.id===studentId);if(!r||!r.paid||attendanceDay>AcademyDates.today()||r.session&&r.session.status!=='scheduled')return;attendanceSaving.add(studentId);button.disabled=true;try{if(r.session){const result=await api('/rest/v1/sessions?id=eq.'+encodeURIComponent(r.session.id)+'&status=eq.scheduled','PATCH',{status});if(!result?.length)throw Error('وضعیت جلسه تغییر کرده؛ صفحه را به‌روزرسانی کنید');}else await api('/rest/v1/sessions','POST',{student_id:studentId,starts_at:attendanceDay+'T'+r.time+':00+03:30',status});await reload();toast(status==='completed'?'حضور هنرجو ثبت شد':'غیبت هنرجو ثبت شد');}catch(e){toast(e.message);await reload().catch(()=>{});}finally{attendanceSaving.delete(studentId);button.disabled=false;}}
function teacherAllocationPanel(){if(!admin)return '';const groups=new Map();for(const p of dashboardPayments()){const s=db.students.find(s=>s.id===p.student_id),key=s?.teacher_id||'unknown';if(!groups.has(key))groups.set(key,{gross:0,share:0});const g=groups.get(key);g.gross+=Number(p.amount)||0;}return `<div class="card"><h3>تفکیک سهم اساتید از دریافتی</h3><p class="sub">۶۰٪ دریافتی متعلق به استاد مربوطه و ۴۰٪ سهم آموزشگاه است. این جدول تخصیص دریافتی است؛ تسویهٔ حقوق در بخش اساتید ثبت می‌شود.</p>${table(['استاد','کل دریافتی کلاس‌ها','سهم استاد · ۶۰٪','سهم آموزشگاه · ۴۰٪'],[...groups].map(([id,g])=>`<tr><td>${id==='unknown'?'نیازمند اتصال به کلاس':window.teacherInline?window.teacherInline(teacher(id)):esc(teacher(id))}</td><td>${money(g.gross)}</td><td>${money(Math.round(g.gross*.6))}</td><td>${money(g.gross-Math.round(g.gross*.6))}</td></tr>`))}</div>`;}
const operationsDashboard=views.dashboard;views.dashboard=function(){return operationsDashboard()+attendancePanel()+teacherAllocationPanel();};
const operationsSchedule=views.schedule;views.schedule=function(){return attendancePanel()+operationsSchedule();};
